arguments.command:
mkdir -p /app/submit && cat > /app/submit/core.c <<'EOF'
/* Core placement table builder + DP for the SCAMP-style pipeline compiler.
 * Input: sorted-by-(net,len) FIB arrays, capacities, max_stride.
 * Output: optimal cuts and per-stage used bits, or "infeasible".
 */
#include <stdint.h>
#include <stdlib.h>
#include <string.h>

typedef unsigned __int128 u128;

#define W 129            /* depths 0..128 */
#define INFN 0xFFFFFFFFFFFFFFFFULL

static uint64_t gcd64(uint64_t a, uint64_t b) { while (b) { uint64_t t = a % b; a = b; b = t; } return a; }

static int cmp_frac(uint64_t an, uint64_t ad, uint64_t bn, uint64_t bd) {
    unsigned __int128 l = (unsigned __int128)an * (unsigned __int128)bd;
    unsigned __int128 r = (unsigned __int128)bn * (unsigned __int128)ad;
    return (l < r) ? -1 : ((l > r) ? 1 : 0);
}

/* returns 0 ok (fills cuts/used/peak), 1 infeasible, -1 error */
int compile_core(const unsigned char *nets, const unsigned char *lens, int n,
                 int max_stride, int S, const int64_t *caps,
                 int32_t *cuts_out, int64_t *used_out,
                 int64_t *peak_num, int64_t *peak_den)
{
    size_t nn = (n > 0) ? (size_t)n : 1;
    u128 *V = (u128 *)malloc(nn * sizeof(u128));
    unsigned char *L = (unsigned char *)malloc(nn);
    if (!V || !L) { free(V); free(L); return -1; }
    for (int i = 0; i < n; i++) {
        u128 x = 0;
        const unsigned char *p = nets + (size_t)i * 16;
        for (int k = 0; k < 16; k++) x = (x << 8) | p[k];
        V[i] = x;
    }
    memcpy(L, lens, (size_t)n);

    int maxg = n + 2;
    int **gstart = (int **)malloc(129 * sizeof(int *));
    int **gid = (int **)malloc(129 * sizeof(int *));
    int *nd = (int *)calloc(129, sizeof(int));
    if (!gstart || !gid || !nd) return -1;
    for (int d = 0; d < 129; d++) {
        gstart[d] = (int *)malloc((size_t)maxg * sizeof(int));
        gid[d] = (int *)malloc(nn * sizeof(int));
        if (!gstart[d] || !gid[d]) return -1;
    }
    for (int d = 0; d < 129; d++) {
        int g = 0, have = 0;
        u128 prevt = 0;
        for (int i = 0; i < n; i++) {
            if (L[i] <= d) { gid[d][i] = -1; continue; }
            u128 t = (d == 0) ? (u128)0 : (V[i] >> (128 - d));
            if (!have || t != prevt) gstart[d][g++] = i;
            gid[d][i] = g - 1;
            prevt = t; have = 1;
        }
        nd[d] = g;
        gstart[d][g] = n;
        if (g + 1 < maxg) gstart[d][g + 1] = n;
    }

    /* length buckets */
    int lstart[130];
    memset(lstart, 0, sizeof(lstart));
    for (int i = 0; i < n; i++) lstart[L[i] + 1]++;
    for (int e = 0; e < 129; e++) lstart[e + 1] += lstart[e];
    int *lenlist = (int *)malloc(nn * sizeof(int));
    int *fillp = (int *)malloc(130 * sizeof(int));
    if (!lenlist || !fillp) return -1;
    memcpy(fillp, lstart, sizeof(lstart));
    for (int i = 0; i < n; i++) lenlist[fillp[L[i]]++] = i;

    int has_default = 0;
    for (int i = 0; i < n; i++) if (L[i] == 0) has_default = 1;

    uint64_t *Ut = (uint64_t *)calloc((size_t)W * W, sizeof(uint64_t));
    if (!Ut) return -1;

    long long *cnt = (long long *)malloc((size_t)(maxg) * sizeof(long long));
    long long *acc = (long long *)malloc((size_t)(maxg) * sizeof(long long));
    if (!cnt || !acc) return -1;

    for (int b = 0; b < 128; b++) {
        int nb = (b == 0) ? 1 : nd[b];
        for (int q = 0; q < nb; q++) { cnt[q] = 0; acc[q] = 0; }
        if (b == 0 && has_default) cnt[0] = 1;
        int emax = b + max_stride; if (emax > 128) emax = 128;
        for (int e = b + 1; e <= emax; e++) {
            for (int k = lstart[e]; k < lstart[e + 1]; k++) {
                int i = lenlist[k];
                int g = (b == 0) ? 0 : gid[b][i];
                cnt[g]++; acc[g] += (e - b + 7) / 8;
            }
            long long eterm = 4 + (e - b + 7) / 8;
            uint64_t U = 0;
            if (e < 128 && nd[e] > 0) {
                int j = 0, ne = nd[e];
                const int *gse = gstart[e];
                const int *gsb = gstart[b];
                for (int q = 0; q < nb; q++) {
                    long long lo, hi;
                    if (b == 0) { lo = 0; hi = n; }
                    else { lo = gsb[q]; hi = (q + 1 < nd[b]) ? gsb[q + 1] : n; }
                    while (j < ne && gse[j] < lo) j++;
                    long long ec = 0;
                    while (j < ne && gse[j] < hi) { j++; ec++; }
                    long long inner = 16 + 4 * cnt[q] + acc[q] + ec * eterm;
                    U += (uint64_t)(64 * ((inner + 7) / 8));
                }
            } else {
                for (int q = 0; q < nb; q++) {
                    long long inner = 16 + 4 * cnt[q] + acc[q];
                    U += (uint64_t)(64 * ((inner + 7) / 8));
                }
            }
            Ut[(size_t)b * W + e] = U;
        }
    }

    /* DP over cuts */
    uint64_t *dpn = (uint64_t *)malloc(sizeof(uint64_t) * (size_t)(S + 1) * W);
    uint64_t *dpd = (uint64_t *)malloc(sizeof(uint64_t) * (size_t)(S + 1) * W);
    int *par = (int *)malloc(sizeof(int) * (size_t)(S + 1) * W);
    if (!dpn || !dpd || !par) return -1;
    for (int k = 0; k <= S; k++)
        for (int e = 0; e < W; e++) { dpn[k * W + e] = INFN; dpd[k * W + e] = 1; par[k * W + e] = -1; }
    dpn[0 * W + 0] = 0; dpd[0 * W + 0] = 1;
    for (int k = 1; k <= S; k++) {
        for (int e = 1; e <= 128; e++) {
            int bmin = e - max_stride; if (bmin < 0) bmin = 0;
            uint64_t bn = INFN, bd = 1; int bp = -1;
            for (int b = bmin; b < e; b++) {
                if (dpn[(k - 1) * W + b] == INFN) continue;
                uint64_t U = Ut[(size_t)b * W + e];
                uint64_t cn = dpn[(k - 1) * W + b], cd = dpd[(k - 1) * W + b];
                /* ratio of max(cn/cd, U/caps[k-1]) */
                uint64_t rn, rd;
                if (cmp_frac(cn, cd, U, (uint64_t)caps[k - 1]) >= 0) { rn = cn; rd = cd; }
                else { rn = U; rd = (uint64_t)caps[k - 1]; }
                if (bp < 0 || cmp_frac(rn, rd, bn, bd) < 0) { bn = rn; bd = rd; bp = b; }
            }
            if (bp >= 0) { dpn[k * W + e] = bn; dpd[k * W + e] = bd; par[k * W + e] = bp; }
        }
    }

    int rc = 1;
    if (dpn[S * W + 128] != INFN) {
        rc = 0;
        int e = 128;
        for (int k = S; k >= 1; k--) { cuts_out[k] = e; e = par[k * W + e]; }
        cuts_out[0] = 0;
        for (int i = 0; i < S; i++) used_out[i] = (int64_t)Ut[(size_t)cuts_out[i] * W + cuts_out[i + 1]];
        uint64_t pn = dpn[S * W + 128], pd = dpd[S * W + 128];
        uint64_t g = gcd64(pn, pd); if (g == 0) g = 1;
        *peak_num = (int64_t)(pn / g); *peak_den = (int64_t)(pd / g);
        if (*peak_den == 0) { *peak_den = 1; *peak_num = 0; }
    }

    free(V); free(L); free(lenlist); free(fillp); free(Ut); free(cnt); free(acc);
    free(dpn); free(dpd); free(par);
    for (int d = 0; d < 129; d++) { free(gstart[d]); free(gid[d]); }
    free(gstart); free(gid); free(nd);
    return rc;
}
EOF
echo written; wc -l /app/submit/core.c
